INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),26,12,'قال موسى: رب إني أخاف أن يكذبوني في الرسالة، ويملأ صدري الغمُّ لتكذيبهم إياي، ولا ينطلق لساني بالدعوة فأرسِلْ جبريل بالوحي إلى أخي هارون؛ ليعاونني. ولهم علي ذنب في قتل رجل منهم، وهو القبطي، فأخاف أن يقتلوني به.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/26/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=26) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
