INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),26,131,'فخافوا الله، وامتثلوا ما أدعوكم إليه فإنه أنفع لكم، واخشوا الله الذي أعطاكم من أنواع النعم ما لا خفاء فيه عليكم، أعطاكم الأنعام: من الإبل والبقر والغنم، وأعطاكم الأولاد، وأعطاكم البساتين المثمرة، وفجَّر لكم الماء من العيون الجارية.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/26/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=26) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
